'use strict';
// Form presentation/review layer. The underlying workflow store remains authoritative.
let formView='current', formLibraryQuery='', formLibraryFilter='all', activeFormSource=0;
let pendingFormApproval=null,pendingFormReset=null,pendingFormReopen=null;
const formLibrary=[
 {id:'followup',title:'Follow-up preferences',kind:'Administrative form',description:'Patient name, preferred time and purpose of follow-up, with a source for each field.',available:true,feature:'F06',fields:'3 source-linked fields'},
 {id:'organisation',title:'Organisation forms',kind:'Template library',description:'Organisation-approved forms, versions and shared templates.',available:false,feature:'F03',fields:'Requires connected template service'},
 {id:'mental-health',title:'Mental health questionnaires',kind:'Assessment library',description:'Clinician-selected instruments with the approved content and scoring workflow.',available:false,feature:'F10',fields:'Requires connected assessment service'},
 {id:'community',title:'Community care assessments',kind:'Assessment library',description:'Barthel, Lawton and MUST capabilities from the Clinical OS register.',available:false,feature:'F11',fields:'Requires connected assessment service'},
 {id:'pdf',title:'PDF form completion',kind:'Document form',description:'Detect supported PDF fields and prepare source-linked entries for review.',available:false,feature:'F05',fields:'Requires authorised file workflow'},
 {id:'scanned',title:'Scanned documents & OCR',kind:'Document form',description:'Extract content from scanned pages before reviewing each proposed entry.',available:false,feature:'F09',fields:'Requires connected OCR service'}
];
function formUiState(){currentPatient();state.formUi=state.formUi||{};if(!state.formUi[state.selectedPatientId])state.formUi[state.selectedPatientId]={version:1,history:state.formApproval?[{version:1,status:'Approved locally',snapshot:JSON.parse(JSON.stringify(state.formApproval))}]:[]};return state.formUi[state.selectedPatientId];}
function currentFormProgress(){const fields=state.formData||[];return {total:fields.length,complete:fields.filter(f=>f.value.trim()).length,reviewed:fields.filter(f=>f.reviewed&&f.value.trim()).length,changed:fields.filter(f=>f.value!==f.original).length};}
function currentFormFingerprint(){return JSON.stringify({patientId:state.selectedPatientId,version:formUiState().version,fields:state.formData,approval:state.formApproval});}
function formProgressMarkup(){const p=currentFormProgress();return `<div class="form-progress-heading"><strong>${p.reviewed} of ${p.total} fields reviewed</strong><span>${p.changed} edited</span></div><progress max="${p.total||1}" value="${p.reviewed}" aria-label="Fields reviewed"></progress><p>${!p.total?'Load a form to begin its field reviews.':p.complete<p.total?(p.total-p.complete)+' required '+(p.total-p.complete===1?'field is':'fields are')+' empty.':p.reviewed<p.total?'Compare every field with its source before approval.':'All fields have a local review confirmation.'}</p>`;}
function formFieldStatus(f){return !f.value.trim()?'<span class="pill amber">Required</span>':f.reviewed?'<span class="pill green">Reviewed</span>':f.value!==f.original?'<span class="pill amber">Edited · review again</span>':'<span class="pill grey">Awaiting review</span>';}
function formSourcePanel(){const f=state.formData?.[activeFormSource];if(!f)return `<div class="workspace-empty"><span class="empty-symbol">${icon('book')}</span><h3>Keep the source in view</h3><p>Load the example form to compare each value with its original source.</p></div>`;return `<div class="source-panel-heading"><span class="eyebrow">SOURCE COMPARISON</span><h2>${esc(f.label)}</h2><p>${esc(f.source)}</p></div><div class="form-source-value"><span>Original source</span><p>${esc(f.original)}</p></div><div class="form-source-value ${f.value!==f.original?'source-value-edited':''}"><span>Current form value ${f.value!==f.original?'<b>Edited</b>':''}</span><p>${f.value.trim()?esc(f.value):'<em>No value entered</em>'}</p></div><p class="fine">${f.value===f.original?'The current value matches the scripted source. Matching does not replace your review.':'This value differs from its source. Check the change before confirming the field.'}</p><div class="source-navigation"><button ${activeFormSource===0?'disabled':''} onclick="showFormSource(${activeFormSource-1},true)" aria-label="Previous source field">← Previous</button><span>${activeFormSource+1} / ${state.formData.length}</span><button ${activeFormSource===state.formData.length-1?'disabled':''} onclick="showFormSource(${activeFormSource+1},true)" aria-label="Next source field">Next →</button></div><p class="form-source-origin">Fictional record · Scripted source · No external record retrieved</p>`;}
function showFormSource(index,focusSource=false){if(!Number.isInteger(index)||!state.formData?.[index])return;activeFormSource=index;const panel=document.getElementById('form-source-panel');if(panel){panel.innerHTML=formSourcePanel();if(focusSource){panel.tabIndex=-1;panel.scrollIntoView?.({block:'nearest'});panel.focus?.({preventScroll:true});}}for(let i=0;i<state.formData.length;i++){document.getElementById('source-button-'+i)?.setAttribute?.('aria-pressed',String(i===index));document.getElementById('form-field-card-'+i)?.classList?.toggle('source-selected',i===index);}}
function editWorkspaceFormField(index,value){if(!state.formData?.[index]||state.formApproval||value.length>500)return;pendingFormApproval=null;pendingFormReset=null;editFormField(index,value);const status=document.getElementById('form-field-status-'+index);if(status)status.innerHTML=formFieldStatus(state.formData[index]);const progress=document.getElementById('form-review-progress');if(progress)progress.innerHTML=formProgressMarkup();const action=document.getElementById('form-final-review');if(action)action.disabled=true;document.getElementById('form-field-'+index)?.setAttribute?.('aria-invalid',String(!value.trim()));showFormSource(index);}
function reviewWorkspaceFormField(index,checked){
 if(!Number.isInteger(index)||typeof checked!=='boolean'||!state.formData?.[index]||state.formApproval)return;
 if(checked&&!state.formData[index].value.trim()){render();document.getElementById('form-field-'+index)?.focus();toast('Complete this required field before recording its review.');return;}
 activeFormSource=index;pendingFormApproval=null;
 state.formData[index].reviewed=checked;
 state.formReviewed=state.formData.every(f=>f.reviewed&&f.value.trim());
 const saved=save();render();document.getElementById('field-review-'+index)?.focus();
 formSaveFeedback(saved,checked?'Field review recorded':'Field review removed');
}
function loadWorkspaceForm(){if(state.formApproval)return toast('Reopen the approved form before changing it.');if(!state.formData){fillForm();activeFormSource=0;render();return;}pendingFormReset={fingerprint:currentFormFingerprint(),patientId:state.selectedPatientId};modal('Reload the source values?',`<p>Your current field values will be saved to local form history before the scripted source values are reloaded.</p><p>All field reviews will need to be completed again.</p>`,`<button onclick="pendingFormReset=null;closeModal()">Keep current form</button><button class="primary" onclick="confirmWorkspaceFormReload()">Save copy & reload</button>`);}
function confirmWorkspaceFormReload(){if(!pendingFormReset||pendingFormReset.patientId!==state.selectedPatientId||pendingFormReset.fingerprint!==currentFormFingerprint()||state.formApproval)return toast('The form changed. Open a fresh reload request.');formUiState().history.unshift({version:formUiState().version,status:'Draft before source reload',snapshot:{patientId:state.selectedPatientId,at:new Date().toISOString(),fields:JSON.parse(JSON.stringify(state.formData)),status:'DRAFT_NOT_SUBMITTED'}});pendingFormReset=null;pendingFormApproval=null;closeModal();fillForm();activeFormSource=0;render();}
function reviewWorkspaceForm(){const p=currentFormProgress();if(state.formApproval)return;if(!p.total||p.complete!==p.total||p.reviewed!==p.total)return toast('Complete and review every required field first.');pendingFormApproval={fingerprint:currentFormFingerprint(),patientId:state.selectedPatientId};modal('Review '+currentPatient().name+'’s form',`<p>Follow-up preferences · Version ${formUiState().version}. Check the exact values below before recording local approval.</p><div class="form-review-list">${state.formData.map(f=>`<div><strong>${esc(f.label)}</strong><p>${esc(f.value)}</p><small>Source: ${esc(f.original)}${f.value!==f.original?' · Edited value':''}</small></div>`).join('')}</div><label class="consent"><input type="checkbox" id="form-final-confirm"><span>I have reviewed these exact values and any changes against their sources.</span></label><p class="fine">Approval stays in this browser. Nothing is sent to a patient or an EPR.</p>`,`<button onclick="pendingFormApproval=null;closeModal()">Back to form</button><button class="primary" onclick="confirmWorkspaceFormApproval()">Approve locally</button>`);}
function confirmWorkspaceFormApproval(){if(!pendingFormApproval||pendingFormApproval.patientId!==state.selectedPatientId||pendingFormApproval.fingerprint!==currentFormFingerprint()||state.formApproval)return toast('The form changed. Open a fresh review.');if(!document.getElementById('form-final-confirm')?.checked){document.getElementById('form-final-confirm')?.focus();return toast('Confirm the final review before approving.');}const p=currentFormProgress();if(p.total===0||p.reviewed!==p.total||p.complete!==p.total)return;state.formApproval={patientId:state.selectedPatientId,at:new Date().toISOString(),fields:state.formData.map(f=>({...f})),status:'DEMO_APPROVED_NOT_SUBMITTED'};formUiState().history.unshift({version:formUiState().version,status:'Approved locally',snapshot:JSON.parse(JSON.stringify(state.formApproval))});pendingFormApproval=null;const saved=audit(state.selectedPatientId+': form approved locally; nothing submitted.');closeModal();render();document.getElementById('form-approval-heading')?.focus();formSaveFeedback(saved,'Form approved locally');}
function requestWorkspaceFormReopen(){if(!state.formApproval)return;pendingFormReopen={fingerprint:currentFormFingerprint(),patientId:state.selectedPatientId};modal('Reopen the approved form?',`<p>The approved version will remain in local history. A new version will open for editing and every field will require review again.</p>`,`<button onclick="pendingFormReopen=null;closeModal()">Keep approved version</button><button class="primary" onclick="confirmWorkspaceFormReopen()">Open new version</button>`);}
function confirmWorkspaceFormReopen(){if(!pendingFormReopen||pendingFormReopen.patientId!==state.selectedPatientId||pendingFormReopen.fingerprint!==currentFormFingerprint()||!state.formApproval)return toast('The form changed. Open a fresh request.');const ui=formUiState();if(!ui.history.some(h=>h.status==='Approved locally'&&JSON.stringify(h.snapshot)===JSON.stringify(state.formApproval)))ui.history.unshift({version:ui.version,status:'Approved locally',snapshot:JSON.parse(JSON.stringify(state.formApproval))});ui.version++;pendingFormReopen=null;pendingFormApproval=null;closeModal();state.formApproval=null;state.formReviewed=false;state.formData?.forEach(f=>f.reviewed=false);const saved=audit(state.selectedPatientId+': form reopened for review.');render();document.getElementById('form-field-0')?.focus();formSaveFeedback(saved,'New form version opened');}
function showWorkspaceFormHistory(){const history=formUiState().history;modal('Form version history',history.length?history.map(h=>`<details class="form-history-item"><summary>Version ${h.version} · ${esc(h.status)}</summary><p class="fine">${esc(h.snapshot.at||'Date not recorded')} · ${esc(h.snapshot.patientId)}</p>${h.snapshot.fields.map(f=>`<div class="history-field"><strong>${esc(f.label)}</strong><p>${esc(f.value)}</p><small>Original source: ${esc(f.original)}</small></div>`).join('')}</details>`).join(''):'<p>No versions have been recorded yet. Approved versions and drafts saved before reloading source values will appear here.</p>');}
function exportWorkspaceFormText(){if(!state.formApproval)return;const p=currentPatient();const ui=formUiState();download(p.id+'-followup-form-v'+ui.version+'.txt',`DEEPSYNAPS CLINICAL ADMIN — SYNTHETIC WORKSPACE\nFollow-up preferences · Version ${ui.version}\n${p.name} (${p.id})\nApproved locally — NOT SUBMITTED\n\n`+state.formApproval.fields.map(f=>`${f.label}: ${f.value}\nSource: ${f.source}\nOriginal value: ${f.original}\nReviewed locally: ${f.reviewed?'Yes':'No'}`).join('\n\n'),'text/plain');}
function filteredFormTemplates(){const q=formLibraryQuery.trim().toLowerCase();return formLibrary.filter(t=>(formLibraryFilter==='all'||t.available)&&[t.title,t.kind,t.description].some(s=>s.toLowerCase().includes(q)));}
function formTemplateCards(){const templates=filteredFormTemplates();return `<p class="result-count" role="status">${templates.length} ${templates.length===1?'template':'templates'}</p><div class="form-template-grid">${templates.map(t=>`<article class="panel form-template-card"><div class="panel-head"><span class="card-icon">${icon(t.kind==='Assessment library'?'book':'form')}</span><span class="pill ${t.available?'green':'grey'}">${t.available?'Available in this build':'Service not connected'}</span></div><span class="eyebrow">${t.kind}</span><h2>${t.title}</h2><p>${t.description}</p><small>${t.fields}</small><button class="${t.available?'primary ':''}wide" onclick="${t.available?"formView='current';render()":`feature('${t.feature}')`}">${t.available?'Open form':'View capability & requirements'} ${icon('arrow')}</button></article>`).join('')}</div>${templates.length?'':'<div class="workspace-empty"><h3>No templates match</h3><p>Try a different term or clear the filters.</p><button onclick="formLibraryQuery=\'\';formLibraryFilter=\'all\';render()">Clear filters</button></div>'}`;}
function formLibraryPage(){return `<div class="form-library-intro"><div><h2>Template library</h2><p>Choose an available workflow or inspect the requirements for connected assessments.</p></div><span class="pill grey">Organisation templates not synced</span></div><div class="form-library-toolbar"><label class="search-field" for="form-library-query">${icon('search')}<input id="form-library-query" type="search" value="${esc(formLibraryQuery)}" placeholder="Search templates and assessments" oninput="formLibraryQuery=this.value;document.getElementById('form-template-results').innerHTML=formTemplateCards()"></label><div class="segmented" aria-label="Template availability"><button aria-pressed="${formLibraryFilter==='all'}" onclick="formLibraryFilter='all';render()">All templates</button><button aria-pressed="${formLibraryFilter==='available'}" onclick="formLibraryFilter='available';render()">Available here</button></div></div><div id="form-template-results">${formTemplateCards()}</div><p class="fine">Clinical assessment content and scoring are not reproduced here. Availability in this workspace is separate from the upstream function register.</p>`;}
function workspaceFormEditor(){const ui=formUiState(),approved=!!state.formApproval,p=currentFormProgress();activeFormSource=Math.min(activeFormSource,Math.max(0,p.total-1));return `<div class="forms-workspace"><section class="panel form-editor-panel"><div class="panel-head"><div><span class="eyebrow">ADMINISTRATIVE FORM</span><h2>Follow-up preferences</h2><p>Template v1 · Document version ${ui.version}</p></div><span class="pill ${approved?'green':'amber'}">${approved?'Approved locally':p.total?'In progress':'Not started'}</span></div>${!state.formData?`<div class="form-start-panel"><span class="empty-symbol">${icon('form')}</span><h3>Start with the available sources</h3><p>Populate three fields from the fictional patient record and scripted conversation. Each value stays linked to its source for review.</p><button class="primary" onclick="loadWorkspaceForm()">${icon('spark')} Fill from example sources</button></div>`:`<div class="form-editor-meta"><span>Changes stay in this browser.</span><button class="text-btn" ${approved?'disabled':''} onclick="loadWorkspaceForm()">Reload source values</button></div>${state.formData.map((f,i)=>`<section class="form-field-card ${i===activeFormSource?'source-selected':''}" id="form-field-card-${i}"><div class="form-field-heading"><label for="form-field-${i}">${i+1}. ${esc(f.label)} <span>Required</span></label><span id="form-field-status-${i}">${formFieldStatus(f)}</span></div><input class="field" id="form-field-${i}" maxlength="500" value="${esc(f.value)}" ${approved?'readonly':''} aria-required="true" aria-invalid="${!f.value.trim()}" aria-describedby="form-source-label-${i}" onfocus="showFormSource(${i})" oninput="editWorkspaceFormField(${i},this.value)"><div class="form-field-source"><span id="form-source-label-${i}">${esc(f.source)}</span><button class="text-btn" id="source-button-${i}" aria-pressed="${i===activeFormSource}" onclick="showFormSource(${i},true)">Compare source ${icon('arrow')}</button></div><label class="form-field-review"><input type="checkbox" id="field-review-${i}" ${f.reviewed?'checked':''} ${approved?'disabled':''} onchange="reviewWorkspaceFormField(${i},this.checked)"><span>I checked this value and any changes against its source.</span></label></section>`).join('')}`}<div class="form-editor-footer"><button onclick="showWorkspaceFormHistory()">${icon('clock')} Version history</button>${approved?'<button onclick="requestWorkspaceFormReopen()">Reopen for editing</button>':''}</div></section><aside class="forms-source-column"><div class="panel form-comparison-panel" id="form-source-panel">${formSourcePanel()}</div><div class="panel form-approval-panel"><span class="eyebrow">REVIEW & FINISH</span><h2 id="form-approval-heading" tabindex="-1">${approved?'Approved · not submitted':'Ready for final review?'}</h2><div id="form-review-progress" class="form-review-progress">${formProgressMarkup()}</div>${approved?'<button class="primary wide" onclick="exportWorkspaceFormText()">Export readable form '+icon('download')+'</button><button class="wide" onclick="exportForm()">Export source-linked JSON</button>':`<button class="primary wide" id="form-final-review" ${!p.total||p.reviewed!==p.total||p.complete!==p.total?'disabled':''} onclick="reviewWorkspaceForm()">Review & approve ${icon('arrow')}</button>`}<p class="fine">${approved?'Approval is local to this development workspace. No patient delivery or EPR acknowledgement exists.':'Check every required field, then review the exact form before recording local approval.'}</p><button class="text-btn" onclick="nav('connections')">Delivery connection status</button></div></aside></div>`;}
uiWorkflowFunctions.F=function(){return `<div class="form-view-switch"><div class="segmented" aria-label="Forms workspace view"><button aria-pressed="${formView==='current'}" onclick="formView='current';render()">Current patient form</button><button aria-pressed="${formView==='library'}" onclick="formView='library';render()">Template library</button></div><span>Patient: <strong>${currentPatient().name}</strong></span></div>`+(formView==='library'?formLibraryPage():workspaceFormEditor());};
const formsPriorPatientSelect=selectPatient;
selectPatient=function(id){if(!demoPatients.some(p=>p.id===id))return;pendingFormApproval=null;pendingFormReset=null;pendingFormReopen=null;activeFormSource=0;formView='current';formsPriorPatientSelect(id);};
render();

function formSaveFeedback(saved,action){toast(saved?action+'. Saved in this browser. Nothing submitted.':action+' in this tab only. Saving failed; use the save recovery options. Nothing submitted.');}
